#!/usr/bin/env python3
"""Own deterministic EPUB2/3 and attack probes; no third-party book content."""
from pathlib import Path
import hashlib,json,zipfile,struct,zlib
root=Path(__file__).resolve().parents[1]
destination=root/'androidApp/src/debug/assets/epub-fixtures'
destination.mkdir(parents=True,exist_ok=True)
def png():
 def chunk(kind,data): return struct.pack('!I',len(data))+kind+data+struct.pack('!I',zlib.crc32(kind+data))
 return b'\x89PNG\r\n\x1a\n'+chunk(b'IHDR',struct.pack('!2I5B',2,2,8,2,0,0,0))+chunk(b'IDAT',zlib.compress((b'\x00'+b'\x22\x88\xcc'*2)*2))+chunk(b'IEND',b'')
manifest=[]
for name in ['epub2','epub3','active-script','external-image','css-external']:
 version='2.0' if name=='epub2' else '3.0'
 body='<p id="start">자체 작성 EPUB 보안·복원 검증 문장입니다.</p><img id="fixture-image" src="image.png" alt="자체 생성 파란 이미지"/>'
 if name=='active-script': body+='<script>document.body.dataset.attack="executed"</script>'
 if name=='external-image': body+='<img src="https://example.invalid/bookreader-canary"/>'
 css='p { color: rgb(17, 34, 51); }'
 if name=='css-external': css+=' @import url("https://example.invalid/bookreader-css-canary"); p { background-image: url("https://example.invalid/bookreader-image-canary"); }'
 entries={'mimetype':'application/epub+zip','META-INF/container.xml':'<container xmlns="urn:oasis:names:tc:opendocument:xmlns:container" version="1.0"><rootfiles><rootfile full-path="OPS/package.opf" media-type="application/oebps-package+xml"/></rootfiles></container>',
 'OPS/package.opf':f'<package xmlns="http://www.idpf.org/2007/opf" version="{version}" unique-identifier="id"><metadata xmlns:dc="http://purl.org/dc/elements/1.1/"><dc:identifier id="id">generated-{name}</dc:identifier><dc:title>자체 생성 EPUB</dc:title><dc:language>ko</dc:language><meta property="dcterms:modified">2026-10-17T00:00:00Z</meta></metadata><manifest><item id="one" href="one.xhtml" media-type="application/xhtml+xml"/><item id="two" href="two.xhtml" media-type="application/xhtml+xml"/><item id="nav" href="nav.xhtml" media-type="application/xhtml+xml" properties="nav"/><item id="ncx" href="toc.ncx" media-type="application/x-dtbncx+xml"/><item id="image" href="image.png" media-type="image/png"/><item id="css" href="style.css" media-type="text/css"/></manifest><spine toc="ncx"><itemref idref="one"/><itemref idref="two"/></spine></package>',
 'OPS/nav.xhtml':'<html xmlns="http://www.w3.org/1999/xhtml" xmlns:epub="http://www.idpf.org/2007/ops"><head><title>목차</title></head><body><nav epub:type="toc"><ol><li><a href="one.xhtml">첫 장</a><ol><li><a href="two.xhtml">둘째 장</a></li></ol></li></ol></nav></body></html>',
 'OPS/toc.ncx':'<ncx xmlns="http://www.daisy.org/z3986/2005/ncx/" version="2005-1"><head/><docTitle><text>자체 생성 EPUB</text></docTitle><navMap><navPoint id="one" playOrder="1"><navLabel><text>첫 장</text></navLabel><content src="one.xhtml"/><navPoint id="two" playOrder="2"><navLabel><text>둘째 장</text></navLabel><content src="two.xhtml"/></navPoint></navPoint></navMap></ncx>',
 'OPS/style.css':css,'OPS/image.png':png()}
 for chapter in ['one','two']:
  text=''.join(f'<p id="p{i}">{chapter} 문단 {i:04d} · 위치를 보존하는 자체 작성 내용입니다.</p>' for i in range(180))
  entries[f'OPS/{chapter}.xhtml']=f'<html xmlns="http://www.w3.org/1999/xhtml"><head><title>{chapter}</title><link rel="stylesheet" href="style.css"/></head><body><h1>{chapter}</h1>{body}{text}<a href="'+('two.xhtml' if chapter=='one' else 'one.xhtml')+'">다른 장</a></body></html>'
 path=destination/f'{name}.epub'
 with zipfile.ZipFile(path,'w') as out:
  for key,value in entries.items():
   info=zipfile.ZipInfo(key,(2026,10,17,0,0,0));info.compress_type=zipfile.ZIP_STORED if key=='mimetype' else zipfile.ZIP_DEFLATED
   out.writestr(info,value.encode() if isinstance(value,str) else value)
 manifest.append({'file':str(path.relative_to(root)),'sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'bytes':path.stat().st_size,'source':'self-generated by scripts/generate-epub-fixtures.py'})
(root/'fixtures/epub-manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n')
